<script lang="ts">
/**
 * Scalar Text Input component
 *
 * A wrapper around the HTML input element with a focusable container.
 *
 * @example
 *   <ScalarTextInput v-model="model" />
 */
export default {}
</script>
<script setup lang="ts">
import { useBindCx } from '@scalar/use-hooks/useBindCx'
import { onMounted, ref } from 'vue'

import { ScalarFormInput } from '../ScalarForm'

const { readonly } = defineProps<{
  readonly?: boolean
}>()

const emit = defineEmits<{
  /** Emitted when the input is clicked */
  (e: 'click', event: MouseEvent): void
}>()

defineSlots<{
  /* Text content to display before the input text */
  prefix?: () => unknown
  /*Text content to display after the input text */
  suffix?: () => unknown
  /* Text content to display to the right of the input */
  aside?: () => unknown
}>()

const model = defineModel<string>()

const input = ref<HTMLInputElement>()

defineOptions({ inheritAttrs: false })
const { stylingAttrsCx, otherAttrs } = useBindCx()

onMounted(() => {
  // Force autofocus if the input has the autofocus attribute
  if ('autofocus' in otherAttrs.value) input.value?.focus()
})

function handleClick(event: MouseEvent) {
  // Re-emit the click event to any consumers
  emit('click', event)

  if (readonly) {
    input.value?.select() // If readonly, select the input on click
  } else {
    input.value?.focus() // If not readonly, focus the input on click
  }
}
</script>
<template>
  <ScalarFormInput
    is="div"
    v-bind="stylingAttrsCx('cursor-text bg-b-1 text-c-1 dark:bg-b-1.5')"
    @click="handleClick">
    <div class="flex items-center flex-1 relative">
      <div
        v-if="$slots.prefix"
        class="select-none whitespace-nowrap text-transparent">
        <slot name="prefix" />
      </div>
      <input
        ref="input"
        v-model="model"
        :aria-readonly="readonly || undefined"
        class="z-1 min-w-0 flex-1 rounded-none border-none bg-transparent placeholder:font-[inherit] focus-within:outline-none"
        :readonly
        v-bind="otherAttrs" />
      <div
        v-if="$slots.prefix || $slots.suffix"
        class="absolute flex items-center inset-0 select-none overflow-hidden whitespace-nowrap">
        <span
          v-if="$slots.prefix"
          class="text-c-2">
          <slot name="prefix" />
        </span>
        <span class="text-transparent">{{ model || $attrs.placeholder }}</span>
        <span
          v-if="$slots.suffix"
          class="text-c-2">
          <slot name="suffix" />
        </span>
      </div>
    </div>
    <slot name="aside" />
  </ScalarFormInput>
</template>
